def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    horizontal_edges=any(x!=bg for x in grid[0]) or any(x!=bg for x in grid[-1])
    for r in range(1,h-1):
        for c in range(1,w-1):
            v=grid[r][c]
            if v==bg: continue
            out[r][c]=4
            if horizontal_edges:
                for dr in (-1,1):
                    rr=r+dr
                    while 0<rr<h-1 and grid[rr][c]==bg:
                        out[rr][c]=v; rr+=dr
            else:
                for dc in (-1,1):
                    cc=c+dc
                    while 0<cc<w-1 and grid[r][cc]==bg:
                        out[r][cc]=v; cc+=dc
    return out
